using System;
using System.Linq;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static class RogueSightTests
 {
  static int Cases,Assertions;static void Check(bool ok,string why){Assertions++;if(!ok)throw new Exception(why);}static void Case(string name,Action work){try{work();Cases++;}catch(Exception e){throw new Exception(name+": "+e.Message,e);}}
  static Guid Epoch=Guid.Parse("44444444-4444-4444-4444-444444444444");
  static (GameState s,UnitState u,PlayerState p,TileData origin,TileData target) Setup(bool idle=false)
  {
   NativeRogueSight.Clear();NativeRegroupSession.States.Clear();NativeRegroupSession.Faults.Clear();NativeGameStateEnvelope.Values.Clear();NativeBlackout.Cells.Clear();
   var s=new GameState{CurrentPlayer=(byte)(idle?2:1)};var u=new UnitState{id=1,coordinates=new(4,4)};var a=new TileData{coordinates=u.coordinates,unit=u};a.Seen.Add(1);var b=new TileData{coordinates=new(5,4),unit=new UnitState{id=2,owner=2,coordinates=new(5,4)}};
   s.Map.Tiles[a.coordinates]=a;s.Map.Tiles[b.coordinates]=b;NativeRegroupSession.States.Add(s);
   var row=new LedgerUnit(1,1,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,3,Rogue:new(2,1,4,new[]{new LedgerSight(4,4),new LedgerSight(5,4)}));
   NativeGameStateEnvelope.Set(s,0,NativeIdentityLedgerCodec.Encode(new(Epoch,2,1,new[]{row},Array.Empty<LedgerReceipt>()),0));return(s,u,new PlayerState(),a,b);
  }
  static LedgerUnit Row(GameState s){var v=NativeGameStateEnvelope.Get(s)!;return NativeIdentityLedgerCodec.Decode(v.Bytes(),v.Revision).Units[0];}
  static void Change(GameState s,Func<LedgerUnit,LedgerUnit> f){var v=NativeGameStateEnvelope.Get(s)!;var l=NativeIdentityLedgerCodec.Decode(v.Bytes(),v.Revision);NativeGameStateEnvelope.Set(s,v.Revision,NativeIdentityLedgerCodec.Encode(l with{Units=new[]{f(l.Units[0])}},v.Revision));}
  static void Visit(GameState s,PlayerState p,TileData tile,bool queued,bool executed=true,Exception? fail=null)
  {NativeRogueSight.BeforeTile(s,p,tile,queued,out var t);if(executed){if(queued&&!tile.GetExplored(p.Id))s.ActionStack.Add(new ExploreAction{PlayerId=p.Id,Coordinates=tile.coordinates});else if(!queued)tile.Seen.Add(p.Id);}NativeRogueSight.AfterTile(executed,t);NativeRogueSight.TileFinished(fail,t);}
  static NativeRogueSight.Source? NativeSource;
  static Exception? FinishSource(Exception? error,NativeRogueSight.Source? source){NativeRogueSight.AfterMove(true,source);return NativeRogueSight.SourceFinished(error,source);}
  static void BeginNative(GameState s,PlayerState p,TileData tile,int range,out NativeRogueSight.Footprint? f){var move=new MoveAction{PlayerId=p.Id,UnitId=tile.unit!.id};s.ActionStack.Add(move);NativeRogueSight.BeforeMove(move,s,out NativeSource);NativeRogueSight.BeforeFootprint(s,p,tile,range,out f);}
  static Exception? EndNative(Exception? error,NativeRogueSight.Footprint? f){var result=NativeRogueSight.FootprintFinished(error,f);return FinishSource(result,NativeSource);}
  public static int Run()
  {
   Case("exact pinned hook surfaces",()=>{var h=new HarmonyLib.Harmony();NativeRogueSight.Install(h);Check(h.Hooks.Count==7,"hookcount");});
   Case("idle local footprint can see without global fog",()=>{var(s,u,p,a,b)=Setup(true);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);bool seen=false;NativeRogueSight.Explored(b,1,ref seen);Check(seen,"savedcell");bool ignore=false;object? result=null;Check(NativeRogueSight.GetUnit(b,s,1,ref ignore,ref result)&&ignore,"rawfog bypass");Check(b.GetUnit(s,1,ignore)==b.unit,"visible attacker");Check(!b.GetExplored(1),"no fog mutation");NativeRogueSight.RetaliationFinished(null,scope);});
   Case("idle local snapshot does not gain global sight",()=>{var(s,u,p,a,b)=Setup(true);Change(s,r=>r with{Rogue=r.Rogue! with{Sight=new[]{new LedgerSight(4,4)}}});b.Seen.Add(1);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);bool seen=true;NativeRogueSight.Explored(b,1,ref seen);Check(!seen,"globalexcluded");bool ignore=false;object? result=b.unit;Check(!NativeRogueSight.GetUnit(b,s,1,ref ignore,ref result)&&result is null,"unitexcluded");NativeRogueSight.RetaliationFinished(null,scope);});
   Case("current blackout veto blocks saved cell",()=>{var(s,u,p,a,b)=Setup(true);NativeBlackout.Cells.Add((s,1,5,4));NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);bool seen=true;NativeRogueSight.Explored(b,1,ref seen);Check(!seen,"blackout");bool ignore=false;object? result=b.unit;Check(!NativeRogueSight.GetUnit(b,s,1,ref ignore,ref result)&&result is null,"blackoutunit");NativeRogueSight.RetaliationFinished(null,scope);});
   Case("native invisible attacker stays undetected",()=>{var(s,u,p,a,b)=Setup(true);b.unit!.Invisible=true;NativeRogueSight.BeforeRetaliation(s,b.unit,u,out var scope);bool ignore=false;object? result=null;Check(NativeRogueSight.GetUnit(b,s,1,ref ignore,ref result)&&ignore,"nativecontinues");Check(b.GetUnit(s,1,ignore) is null,"invisibilitypreserved");NativeRogueSight.RetaliationFinished(null,scope);});
   Case("active commander uses ordinary global visibility",()=>{var(s,u,p,a,b)=Setup();NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);Check(scope is null,"noscope");bool seen=false;NativeRogueSight.Explored(b,1,ref seen);Check(!seen,"nativefalse");});
   Case("normal unit never overrides sight",()=>{var(s,u,p,a,b)=Setup(true);Change(s,r=>r with{Rogue=null});NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);Check(scope is null,"normal");});
   Case("wrong observer unchanged",()=>{var(s,u,p,a,b)=Setup(true);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);bool seen=false;NativeRogueSight.Explored(b,2,ref seen);Check(!seen,"otherplayer");NativeRogueSight.RetaliationFinished(null,scope);});
   Case("foreign map and wrong state unchanged",()=>{var(s,u,p,a,b)=Setup(true);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);var foreign=new TileData{coordinates=b.coordinates};bool seen=false;NativeRogueSight.Explored(foreign,1,ref seen);Check(!seen,"foreigntile");bool ignore=false;object? result=null;Check(NativeRogueSight.GetUnit(b,new GameState(),1,ref ignore,ref result)&&!ignore,"foreignstate");NativeRogueSight.RetaliationFinished(null,scope);});
   Case("scope finalizer preserves native failure and restores",()=>{var(s,u,p,a,b)=Setup(true);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var scope);var error=new Exception("native");Check(ReferenceEquals(NativeRogueSight.RetaliationFinished(error,scope),error),"failure");bool seen=false;NativeRogueSight.Explored(b,1,ref seen);Check(!seen,"cleanup");});
   Case("clear invalidates nested callbacks",()=>{var(s,u,p,a,b)=Setup(true);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var one);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var two);NativeRogueSight.Clear();NativeRogueSight.RetaliationFinished(null,two);NativeRogueSight.RetaliationFinished(null,one);bool seen=false;NativeRogueSight.Explored(b,1,ref seen);Check(!seen,"noresurrection");});
   Case("normal nested callback restores outer",()=>{var(s,u,p,a,b)=Setup(true);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var one);NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var two);NativeRogueSight.RetaliationFinished(null,two);bool seen=false;NativeRogueSight.Explored(b,1,ref seen);Check(seen,"outerrestored");NativeRogueSight.RetaliationFinished(null,one);});
   Case("native completed footprint replaces old local cells",()=>{var(s,u,p,a,b)=Setup();BeginNative(s,p,a,1,out var f);Visit(s,p,a,false);EndNative(null,f);Check(Row(s).Rogue!.Sight!.SequenceEqual(new[]{new LedgerSight(4,4)}),"replacement");Check(!b.GetExplored(1),"fogunchanged");});
   Case("queued footprint persists pending only",()=>{var(s,u,p,a,b)=Setup();BeginNative(s,p,a,1,out var f);Visit(s,p,a,true);Visit(s,p,b,true);EndNative(null,f);var r=Row(s).Rogue!;Check(r.Sight!.Length==1&&r.PendingSight!.SequenceEqual(new[]{new LedgerSight(5,4)}),"pending");Check(!b.GetExplored(1),"notpremature");});
   Case("successful queued completion promotes persisted pending",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{Sight=null,PendingSight=new[]{new LedgerSight(5,4)}}});var action=new ExploreAction{Coordinates=b.coordinates};s.ActionStack.Add(action);NativeRogueSight.Clear();NativeRogueSight.BeforeExplore(action,s,out var e);b.Seen.Add(1);NativeRogueSight.AfterExplore(true,e);NativeRogueSight.ExploreFinished(null,e);Check(Row(s).Rogue!.Sight!.SequenceEqual(new[]{new LedgerSight(5,4)})&&Row(s).Rogue!.PendingSight is null,"loadpromotion");});
   Case("failed queued action keeps pending",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{Sight=null,PendingSight=new[]{new LedgerSight(5,4)}}});var action=new ExploreAction{Coordinates=b.coordinates};s.ActionStack.Add(action);NativeRogueSight.BeforeExplore(action,s,out var e);b.Seen.Add(1);NativeRogueSight.AfterExplore(true,e);var error=new Exception();Check(ReferenceEquals(error,NativeRogueSight.ExploreFinished(error,e)),"failure");Check(Row(s).Rogue!.Sight is null&&Row(s).Rogue!.PendingSight!.Length==1,"unchanged");});
   Case("skipped queued action cannot promote global sight",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{Sight=null,PendingSight=new[]{new LedgerSight(5,4)}}});var action=new ExploreAction{Coordinates=b.coordinates};s.ActionStack.Add(action);NativeRogueSight.BeforeExplore(action,s,out var e);b.Seen.Add(1);NativeRogueSight.AfterExplore(false,e);NativeRogueSight.ExploreFinished(null,e);Check(Row(s).Rogue!.Sight is null,"skipped");});
   Case("unbound direct Explore call cannot promote",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{PendingSight=new[]{new LedgerSight(5,4)}}});NativeRogueSight.BeforeExplore(new ExploreAction{Coordinates=b.coordinates},s,out var e);Check(e is null,"notqueued");});
   Case("wrong player queued action cannot promote",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{PendingSight=new[]{new LedgerSight(5,4)}}});var action=new ExploreAction{Coordinates=b.coordinates,PlayerId=2};s.ActionStack.Add(action);NativeRogueSight.BeforeExplore(action,s,out var e);Check(e is null,"wrongplayer");});
   Case("new command acquisition cancels old pending",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=new LedgerRogue(2,3,5)});var action=new ExploreAction{Coordinates=b.coordinates};s.ActionStack.Add(action);NativeRogueSight.BeforeExplore(action,s,out var e);Check(e is null,"newcommand");});
   Case("wrong sight range refuses capture",()=>{var(s,u,p,a,b)=Setup();BeginNative(s,p,a,2,out var f);Check(f is null,"wrongrange");});
   Case("idle source never captures at turn boundary",()=>{var(s,u,p,a,b)=Setup(true);var before=NativeGameStateEnvelope.Get(s)!.Bytes();BeginNative(s,p,a,1,out var f);Check(f is null,"idle");Check(before.SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes()),"unchanged");});
   Case("inaccessible source cannot autonomously discover",()=>{var(s,u,p,a,b)=Setup();a.Seen.Clear();BeginNative(s,p,a,1,out var f);Check(f is null,"coveredorigin");});
   Case("exchange collection stages without publishing",()=>{var(s,u,p,a,b)=Setup();var c=new NativeRogueSight.Collection();var snap=NativeGameStateEnvelope.Get(s)!;using(NativeRogueSight.ExchangeSource(s,1,a,c)){NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Visit(s,p,b,true);NativeRogueSight.FootprintFinished(null,f);}Check(snap.Bytes().SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes()),"notpublished");var merged=c.Merge(NativeIdentityLedgerCodec.Decode(snap.Bytes(),snap.Revision));Check(merged.Units[0].Rogue!.PendingSight!.Length==1,"merged");});
   Case("exchange does not attach to reacquired Rogue",()=>{var(s,u,p,a,b)=Setup();var c=new NativeRogueSight.Collection();using(NativeRogueSight.ExchangeSource(s,1,a,c)){NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Visit(s,p,a,true);NativeRogueSight.FootprintFinished(null,f);}Change(s,r=>r with{Rogue=new(2,3,5)});var snap=NativeGameStateEnvelope.Get(s)!;var merged=c.Merge(NativeIdentityLedgerCodec.Decode(snap.Bytes(),snap.Revision));Check(merged.Units[0].Rogue!.Sight is null,"differentcommand");});
   Case("movement source captures final footprint even newly entered fog",()=>{var(s,u,p,a,b)=Setup();var move=new MoveAction();s.ActionStack.Add(move);NativeRogueSight.BeforeMove(move,s,out var source);a.unit=null;b.unit=u;u.coordinates=b.coordinates;NativeRogueSight.BeforeFootprint(s,p,b,1,out var f);Check(f is not null,"authorizedmovement");Visit(s,p,b,true);NativeRogueSight.FootprintFinished(null,f);FinishSource(null,source);Check(Row(s).Rogue!.Sight is null&&Row(s).Rogue!.PendingSight!.Contains(new(5,4)),"finalposition");});
   Case("failed movement does not publish staged footprint",()=>{var(s,u,p,a,b)=Setup();var before=NativeGameStateEnvelope.Get(s)!.Bytes();var move=new MoveAction();s.ActionStack.Add(move);NativeRogueSight.BeforeMove(move,s,out var source);NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Visit(s,p,b,true);NativeRogueSight.FootprintFinished(null,f);FinishSource(new Exception(),source);Check(before.SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes()),"rollback");});
   Case("skipped native footprint visit records no discovery",()=>{var(s,u,p,a,b)=Setup();BeginNative(s,p,a,1,out var f);Visit(s,p,b,true,false);EndNative(null,f);Check(Row(s).Rogue!.Sight is null&&Row(s).Rogue!.PendingSight is null,"skip");});
   Case("capture duplicates remain canonical",()=>{var(s,u,p,a,b)=Setup();BeginNative(s,p,a,1,out var f);Visit(s,p,a,false);Visit(s,p,a,false);EndNative(null,f);Check(Row(s).Rogue!.Sight!.Length==1,"dedup");});
   Case("coast candidate exact new wrapper gets local sight before publication",()=>{var(s,u,p,a,b)=Setup();var old=Row(s);u.id=9;var candidate=old with{NativeId=9};var c=new NativeRogueSight.Collection();using(NativeRogueSight.ExchangeSource(s,1,a,c,candidate)){NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Check(f is not null,"candidateaccepted");Visit(s,p,a,true);NativeRogueSight.FootprintFinished(null,f);}var snap=NativeGameStateEnvelope.Get(s)!;var l=NativeIdentityLedgerCodec.Decode(snap.Bytes(),snap.Revision);var merged=c.Merge(l with{Units=new[]{candidate}});Check(merged.Units[0].Rogue!.Sight!.SequenceEqual(new[]{new LedgerSight(4,4)}),"candidatefootprint");Check(Row(s).NativeId==1,"notpublished");});
   Case("coast candidate wrong wrapper id refused",()=>{var(s,u,p,a,b)=Setup();var old=Row(s);u.id=9;var c=new NativeRogueSight.Collection();using(NativeRogueSight.ExchangeSource(s,1,a,c,old)){NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Check(f is null,"wrongid");}});
   Case("coast candidate wrong commander or stale turn refused",()=>{var(s,u,p,a,b)=Setup();var old=Row(s);u.id=9;foreach(var rogue in new[]{new LedgerRogue(2,3,4),new LedgerRogue(2,1,3)}){using(NativeRogueSight.ExchangeSource(s,1,a,new(),old with{NativeId=9,Rogue=rogue})){NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Check(f is null,"wrongauthority");}}});
   Case("foreign source tile rejected",()=>{var(s,u,p,a,b)=Setup();bool failed=false;try{using var q=NativeRogueSight.ExchangeSource(s,1,new TileData{coordinates=a.coordinates,unit=u},new());}catch(System.IO.InvalidDataException){failed=true;}Check(failed,"foreigntile");});
   Case("unready lifecycle disables scope",()=>{var(s,u,p,a,b)=Setup(true);NativeRegroupSession.States.Clear();NativeRogueSight.BeforeRetaliation(s,b.unit!,u,out var f);Check(f is null,"unready");});
   Case("duplicate Explore completion leaves revision stable",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{Sight=null,PendingSight=new[]{new LedgerSight(5,4)}}});var action=new ExploreAction{Coordinates=b.coordinates};s.ActionStack.Add(action);NativeRogueSight.BeforeExplore(action,s,out var e);b.Seen.Add(1);NativeRogueSight.AfterExplore(true,e);NativeRogueSight.ExploreFinished(null,e);long revision=NativeGameStateEnvelope.Get(s)!.Revision;NativeRogueSight.ExploreFinished(null,e);Check(NativeGameStateEnvelope.Get(s)!.Revision==revision,"idempotent");});
   Case("unscoped static native footprint cannot refresh Rogue sight",()=>{var(s,u,p,a,b)=Setup();var before=NativeGameStateEnvelope.Get(s)!.Bytes();NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Check(f is null,"unapprovedsource");Check(before.SequenceEqual(NativeGameStateEnvelope.Get(s)!.Bytes()),"noboundaryrefresh");});
   Case("accepted collection publishes only bound current ledger",()=>{var(s,u,p,a,b)=Setup();var c=new NativeRogueSight.Collection();using(NativeRogueSight.ExchangeSource(s,1,a,c)){NativeRogueSight.BeforeFootprint(s,p,a,1,out var f);Visit(s,p,a,true);NativeRogueSight.FootprintFinished(null,f);}NativeRogueSight.CompleteCollection(s,c);Check(Row(s).Rogue!.Sight!.Length==1,"accepted");NativeRegroupSession.States.Clear();bool denied=false;try{NativeRogueSight.CompleteCollection(s,c);}catch(System.IO.InvalidDataException){denied=true;}Check(denied,"lostbinding");});
   Case("covered pending Explore waits for completed permit consumption",()=>{var(s,u,p,a,b)=Setup();Change(s,r=>r with{Rogue=r.Rogue! with{Sight=null,PendingSight=new[]{new LedgerSight(5,4)}}});NativeBlackout.Cells.Add((s,1,5,4));var action=new ExploreAction{Coordinates=b.coordinates};s.ActionStack.Add(action);NativeRogueSight.BeforeExplore(action,s,out var e);b.Seen.Add(1);NativeRogueSight.AfterExplore(true,e);NativeBlackout.Cells.Clear();NativeRogueSight.ExploreFinished(null,e);Check(Row(s).Rogue!.Sight!.Contains(new(5,4)),"permittednativecompletion");});
   Console.WriteLine("{\"passed\":true,\"cases\":"+Cases+",\"assertions\":"+Assertions+",\"nativeGame\":\"NOT RUN\"}");return 0;
  }
 }
}
